UPDATE truss.feed_tx t SET finalized_generation = $3::bigint, manifest_bytes = $4::pg_catalog.bytea, manifest_sha256 = $5::pg_catalog.bytea WHERE false RETURNING t.source_epoch, t.feed_profile, t.original_writer_xid::pg_catalog.text AS original_writer_xid, t.membership_generation::pg_catalog.text AS membership_generation, t.finalized_generation::pg_catalog.text AS finalized_generation, pg_catalog.encode(t.manifest_bytes, 'hex') AS manifest_bytes_hex, pg_catalog.encode(t.manifest_sha256, 'hex') AS manifest_sha256_hex